import 'offline-js';
import { NetworkEvents, OfflineEventName } from './types';
import EventEmitter from 'eventemitter3';
import { DeviceType } from './device-info/device-type';

Offline.options = {
    requests: false,
    reconnect: {
        initialDelay: 3,
        delay: 1.5
    }
};
const OFFLINE_EVENTS: OfflineEventName[] = [
    'up',
    'down',
    'confirmed-up',
    'confirmed-down',
    'checking',
    'reconnect:started',
    'reconnect:stopped',
    'reconnect:connecting',
    'reconnect:failure'
];

export class Network extends EventEmitter<NetworkEvents> {
    protected connectedStatus: boolean = true;
    protected mLastOfflineEvent: OfflineEventName = 'up';

    protected get lastOfflineEvent() { return this.mLastOfflineEvent; }
    protected set lastOfflineEvent(value: OfflineEventName) {
        const isUpOrDown = value.includes('up') || value.includes('down');
        if (isUpOrDown) {
            this.connectedStatus = value.includes('up');
        }
        this.mLastOfflineEvent = value;
    }

    constructor(private deviceType: DeviceType) {
        super();
        this.setupBrowserEvents();
    }

    get isConnected() {
        const connection = (window as any).navigator.connection;    
        if (this.deviceType.isApp) {
            return connection ? connection.type !== 'none' : window.navigator.onLine;
        } else {
            return this.connectedStatus;
        }
    }

    public markDown() {
        // love it, offline-js has a method markDown on its Offline var but hasn't defined it in @types/offline-js
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        (Offline as any).markDown();
    }

    private onOfflineEvent(nextEvent: OfflineEventName) {
        //push the event up
        const connectionStatus = this.connectedStatus;
        this.lastOfflineEvent = nextEvent;
        const connectionStatusChanged = connectionStatus !== nextEvent.includes('up');
        const isUpOrDown = nextEvent.includes('up') || nextEvent.includes('down');
        if (connectionStatusChanged && isUpOrDown) {
            this.emit('isConnected', this.connectedStatus);
        }
    }
    
    private setupBrowserEvents() {
        OFFLINE_EVENTS.forEach((event, index) =>
            Offline.on(event, () => {
                this.onOfflineEvent(OFFLINE_EVENTS[index]);
            }));
    }
}
